import {KitchenGame,RECIPES,INGREDIENTS} from './core.js';
import {KitchenScene,drawFood} from './scene.js';
const $=id=>document.getElementById(id),game=new KitchenGame(),pIds=['dough','sauce','mozzarella','pepperoni','mushroom'],bIds=['bunBottom','patty','cheese','lettuce','tomato','bunTop'];
const input={dispatch(action){game.dispatch(action);}};
let sound=false,audio=null,lastEvent='',lastMessage='',orderSignature='',ingredientSignature='',summaryShown=false,best=0;
try{best=Number(localStorage.getItem('sizzle-best')||0);}catch{}
const fmt=n=>`${String(Math.floor(n/60)).padStart(2,'0')}:${String(Math.floor(n%60)).padStart(2,'0')}`;
function chirp(event){if(!sound)return;try{audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();let o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.type='sine';const now=audio.currentTime;o.frequency.setValueAtTime(event==='serve'?660:event==='ready'?880:400,now);o.frequency.exponentialRampToValueAtTime(event==='serve'?990:520,now+.1);g.gain.setValueAtTime(.045,now);g.gain.exponentialRampToValueAtTime(.001,now+.2);o.start();o.stop(now+.21);}catch{}}
function sceneAction(id){let s=game.state;if(['pizza','burger'].includes(id))input.dispatch({type:'SELECT_STATION',station:id});else if(id==='oven')input.dispatch({type:s.oven?'COLLECT_OVEN':'BAKE'});else input.dispatch({type:s.grill?'COLLECT_GRILL':'GRILL'});}
const scene=new KitchenScene($('kitchen'),sceneAction);
function renderOrders(s){const signature=s.orders.map(o=>o.id+o.recipeId).join('|')+s.selectedOrder+s.mode;
 if(signature!==orderSignature){orderSignature=signature;$('orders').innerHTML=s.orders.map(o=>{let r=RECIPES.find(r=>r.id===o.recipeId);return `<button class="ticket ${s.selectedOrder===o.id?'selected':''}" data-order="${o.id}" aria-pressed="${s.selectedOrder===o.id}"><div class="ticket-top"><span>#${String(o.id).padStart(3,'0')}</span><span class="ticket-label">${r.type==='pizza'?'PIZZA':'BURGER'}</span></div><div class="ticket-food"><span class="ticket-icon">${r.type==='pizza'?'🍕':'🍔'}</span><div><b>${r.name}</b><small>${r.type==='pizza'?'FRESH FROM THE OVEN':'STACKED WITH LOVE'}</small></div><span class="ticket-price">¥${r.price}</span></div><div class="ticket-ingredients">${r.ingredients.map(i=>INGREDIENTS[i].name).join(' · ')}</div><div class="ticket-bottom"><span class="selected-mark">${s.selectedOrder===o.id?'● In progress':'○ Select ticket'}</span><span data-patience="${o.id}">${s.mode==='practice'?'No rush':Math.ceil(o.remaining)+' sec'}</span></div><div class="patience"><i data-bar="${o.id}" style="width:100%"></i></div></button>`;}).join('');}
 for(const o of s.orders){let t=document.querySelector(`[data-patience="${o.id}"]`),b=document.querySelector(`[data-bar="${o.id}"]`);if(t)t.textContent=s.mode==='practice'?'No rush':Math.max(0,Math.ceil(o.remaining))+' sec';if(b){b.style.width=(s.mode==='practice'?100:o.remaining/o.total*100)+'%';b.style.background=o.remaining<25&&s.mode==='shift'?'#d79264':'#90a97d';}}
}
function appliance(s,slot){let a=s[slot],isOven=slot==='oven',ready=a&&a.elapsed>=a.duration,burned=a&&(isOven?a.dish.burned:a.burned);$(slot+'-status').textContent=burned?'Burnt! Collect it':ready?'Ready! Collect it':a?`${Math.ceil(a.duration-a.elapsed)} sec left`:!isOven&&s.pattyReady?'Patty ready':`Idle · ${isOven?7:5} sec`;
 $(slot+'-progress').style.width=(a?Math.min(100,a.elapsed/a.duration*100):!isOven&&s.pattyReady?100:0)+'%';$(slot+'-panel').className='appliance'+(ready?' ready':'')+(burned?' burned':'');$(slot+'-action').innerHTML=(a?(ready?(isOven?'Collect pizza':'Collect patty'):'Cooking…'):isOven?'Bake pizza':s.pattyReady?'Patty ready':'Grill a patty')+' <span>→</span>';$(slot+'-action').disabled=s.paused||s.ended||(!!a&&!ready)||(!isOven&&s.pattyReady);
}
function render(s){$('revenue').textContent='¥'+s.revenue;$('served').textContent=String(s.served).padStart(2,'0');$('score').textContent=s.score;$('clock').textContent=fmt(s.mode==='shift'?Math.ceil(s.remaining):s.elapsed);$('timer-label').textContent=s.mode==='shift'?'Time left':'Practice time';$('mode-label').textContent=s.ended?'Closed':s.paused?'On a break':s.mode==='practice'?'Practicing':'Open for orders';$('mode-hint').textContent=s.mode==='practice'?'Take your time. Good food is worth it.':'Serve something delicious while it is hot.';$('practice').classList.toggle('active',s.mode==='practice');$('shift').classList.toggle('active',s.mode==='shift');$('shift').innerHTML=(s.mode==='shift'?'Restart shift':'Start a shift')+' <span>↗</span>';$('pause-overlay').hidden=!s.paused;$('pause').textContent=s.paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',s.paused?'Resume game':'Pause game');$('pause').disabled=s.ended;renderOrders(s);
 for(const btn of document.querySelectorAll('[data-station]')){btn.classList.toggle('active',btn.dataset.station===s.station);btn.setAttribute('aria-pressed',String(btn.dataset.station===s.station));}
 let pizza=s.station==='pizza',d=s[s.station],r=game.recipe,ids=pizza?pIds:bIds;
 $('prep-eyebrow').textContent=pizza?'PIZZA STATION':'BURGER STATION';$('prep-title').textContent=pizza?"Let's make a fresh pizza":"Let's stack a happy burger";$('dish-status').textContent=d.burned?'Burnt — clear and start again':d.cooked?'Freshly baked. Ready to serve.':d.ingredients.includes('bunTop')?'Burger assembled. Check, then serve.':d.ingredients.length?`${d.ingredients.length} ingredients added`:pizza?'Start with the dough':'Start with a bottom bun';
 const iSig=s.station+d.ingredients.join(',')+(r?.id??'')+s.pattyReady+s.paused+s.ended+d.cooked;
 if(iSig!==ingredientSignature){ingredientSignature=iSig;$('ingredients').innerHTML=ids.map((id,i)=>`<button class="ingredient ${d.ingredients.includes(id)?'added':''} ${r?.type===s.station&&r.ingredients.includes(id)?'required':''}" data-ingredient="${id}" ${s.paused||s.ended||d.cooked||d.ingredients.includes(id)?'disabled':''} aria-label="Add ${INGREDIENTS[id].name.toLowerCase()}"><kbd>${i+1}</kbd><span>${INGREDIENTS[id].icon}</span><small>${id==='patty'&&!s.pattyReady?'Grill first':INGREDIENTS[id].name}</small></button>`).join('');}
 $('recipe-check').innerHTML=r?.type===s.station?'<span>Recipe</span>'+r.ingredients.map(id=>`<span class="check ${d.ingredients.includes(id)?'done':''}">${d.ingredients.includes(id)?'✓':'○'} ${INGREDIENTS[id].name}</span>`).join(''):'<span>Select a ticket for this station.</span>';
 appliance(s,'oven');appliance(s,'grill');$('clear').disabled=s.paused||s.ended;$('serve').disabled=s.paused||s.ended;$('message').className='message '+s.messageType;$('message').querySelector('p').textContent=s.message;$('combo-label').textContent=s.combo?`GOOD JOB, CHEF. COMBO ×${s.combo}`:"LET'S COOK SOMETHING GOOD.";
 if(lastMessage!==s.message||lastEvent!==s.event){if(['serve','ready','ingredient','cook'].includes(s.event))chirp(s.event);lastMessage=s.message;lastEvent=s.event;}
 if(s.ended&&!summaryShown){summaryShown=true;best=Math.max(best,s.score);try{localStorage.setItem('sizzle-best',String(best));}catch{}$('summary-stats').innerHTML=`<div><b>¥${s.revenue}</b><span>Revenue</span></div><div><b>${s.served}</b><span>Orders served</span></div><div><b>${s.score}</b><span>Shift score</span></div>`;$('best-score').textContent=`Best: ${best} points · Missed: ${s.missed} orders`;$('summary-dialog').showModal();}
}
game.subscribe(render);render(game.state);
function reset(mode){summaryShown=false;orderSignature='';ingredientSignature='';if($('summary-dialog').open)$('summary-dialog').close();input.dispatch({type:'RESET',mode});}
// Input adapter: semantic commands are shared across pointer, touch and keyboard.
$('orders').addEventListener('click',e=>{const b=e.target.closest('[data-order]');if(b)input.dispatch({type:'SELECT_ORDER',id:Number(b.dataset.order)});});
$('ingredients').addEventListener('click',e=>{const b=e.target.closest('[data-ingredient]');if(b)input.dispatch({type:'ADD',ingredient:b.dataset.ingredient});});
document.querySelectorAll('[data-station]').forEach(b=>b.addEventListener('click',()=>input.dispatch({type:'SELECT_STATION',station:b.dataset.station})));
$('oven-action').onclick=()=>input.dispatch({type:game.state.oven?'COLLECT_OVEN':'BAKE'});$('grill-action').onclick=()=>input.dispatch({type:game.state.grill?'COLLECT_GRILL':'GRILL'});$('serve').onclick=()=>input.dispatch({type:'SERVE'});$('clear').onclick=()=>input.dispatch({type:'CLEAR'});$('pause').onclick=$('resume').onclick=()=>input.dispatch({type:'PAUSE'});$('practice').onclick=()=>{if(game.state.mode!=='practice'||game.state.ended)reset('practice');};$('shift').onclick=$('again').onclick=()=>reset('shift');$('back-practice').onclick=()=>reset('practice');
let wasPaused=true;
function openDialog(id){wasPaused=game.state.paused;if(!wasPaused&&!game.state.ended)input.dispatch({type:'PAUSE'});$(id).showModal();}
for(const id of ['help-dialog','architecture-dialog']){$(id).querySelector('.close-dialog').onclick=()=>$(id).close();$(id).addEventListener('close',()=>{if(!wasPaused&&game.state.paused&&!game.state.ended)input.dispatch({type:'PAUSE'});});}
$('help').onclick=$('view-help').onclick=()=>openDialog('help-dialog');$('architecture').onclick=()=>openDialog('architecture-dialog');document.querySelector('.close-guide').onclick=()=>$('help-dialog').close();$('sound').onclick=()=>{sound=!sound;$('sound').style.background=sound?'#e7edde':'transparent';$('sound').setAttribute('aria-label',sound?'Mute sound':'Enable sound');$('sound').title=sound?'Mute sound':'Enable sound';if(sound)chirp('ready');};
window.addEventListener('keydown',e=>{if(e.target.matches('input,textarea,select')||document.querySelector('dialog[open]')||e.repeat)return;if(/^[1-6]$/.test(e.key)){const id=(game.state.station==='pizza'?pIds:bIds)[Number(e.key)-1];if(id){e.preventDefault();input.dispatch({type:'ADD',ingredient:id});}}if(e.key==='Enter'&&!e.target.closest('button,a')){e.preventDefault();input.dispatch({type:'SERVE'});}if(e.code==='Space'&&!e.target.closest('button,a')){e.preventDefault();input.dispatch({type:'PAUSE'});}if(['p','b'].includes(e.key.toLowerCase())){e.preventDefault();input.dispatch({type:'SELECT_STATION',station:e.key.toLowerCase()==='p'?'pizza':'burger'});}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&!game.state.paused&&!game.state.ended)input.dispatch({type:'PAUSE'});});
let last=performance.now(),acc=0;function frame(now){let dt=Math.min((now-last)/1000,.5);last=now;acc+=dt;if(acc>=.1){game.tick(acc);acc=0;}scene.render(game.state,now/1000);const cv=$('dish'),ctx=cv.getContext('2d'),r=cv.getBoundingClientRect(),dpr=Math.min(devicePixelRatio||1,2);if(cv.width!==Math.round(r.width*dpr)||cv.height!==Math.round(r.height*dpr)){cv.width=Math.round(r.width*dpr);cv.height=Math.round(r.height*dpr);}ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,r.width,r.height);drawFood(ctx,r.width/2,r.height*.6,Math.min(r.width/160,r.height/110)*.82,game.state[game.state.station],now/1000);requestAnimationFrame(frame);}requestAnimationFrame(frame);
